INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('bbq-chicken-and-rice-casserole','BBQ Chicken and Rice Casserole','Comforting casserole with shredded chicken, broccoli rice, and BBQ sauce topped with crispy bacon','american','easy',35,5,40,6,380,1,0,0,0,1,'chicken',2,0.757,8,1,'[{"name":"Butter","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"dairy"},{"name":"Broccoli rice","quantity":4,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"Cooked white rice","quantity":4.5,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"Garlic powder","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Shredded chicken","quantity":4,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"BBQ sauce","quantity":1.5,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"Bacon strips","quantity":6,"unit":"unit","unit_norm":"","category":"meat"},{"name":"Green onions","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"produce"}]','["Preheat the oven to 350°F","Melt butter in a large sauté pan over medium heat, add broccoli rice and season with salt","Cook for 3-4 minutes until softened, then remove from heat","Add cooked white rice, garlic powder, pepper, and remaining salt to the pan with broccoli","Transfer to an 8-inch square casserole dish","Toss shredded chicken with BBQ sauce and spread on top of the rice mixture","Top with bacon and bake for 30 minutes until top is starting to brown","Garnish with green onions and serve"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('white-chicken-chili','White Chicken Chili','Creamy and flavorful chicken chili with white beans, green chilis, and lime','american','easy',15,5,20,4,420,1,0,0,0,1,'chicken',2,0.925,12,0,'[{"name":"Olive oil","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Yellow onion","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":2,"unit":"cloves","unit_norm":"clove","category":"produce"},{"name":"Diced green chilis","quantity":4,"unit":"oz","unit_norm":"oz","category":"pantry"},{"name":"Shredded chicken","quantity":3,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"Chicken broth","quantity":5,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"White beans","quantity":15,"unit":"oz","unit_norm":"oz","category":"pantry"},{"name":"Frozen corn","quantity":1,"unit":"cup","unit_norm":"cup","category":"frozen"},{"name":"Sour cream","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"Lime","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"Bacon","quantity":4,"unit":"strips","unit_norm":"strips","category":"meat"},{"name":"Avocado","quantity":1,"unit":"unit","unit_norm":"","category":"produce"}]','["Heat olive oil in a large saucepan over medium heat","Add onion and garlic, sauté for 3-4 minutes until translucent","Add green chilis and cook for 1 minute until fragrant","Add shredded chicken and seasonings, stir to combine","Pour in broth, increase heat, stir in beans and corn","Cover and simmer for 10 minutes","Turn off heat and stir in sour cream, lime juice, and bacon","Garnish with avocado, cilantro, and lime wedges"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-and-broccoli-fried-rice','Chicken and Broccoli Fried Rice','Quick Asian-inspired fried rice with tender chicken, broccoli, and scrambled eggs','asian','easy',15,5,20,4,390,1,0,0,0,1,'chicken',2,0.925,11,0,'[{"name":"Avocado oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Eggs","quantity":2,"unit":"unit","unit_norm":"","category":"dairy"},{"name":"Ginger","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"produce"},{"name":"Garlic","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"produce"},{"name":"Broccoli florets","quantity":3,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"Carrots","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Shredded chicken","quantity":3,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"Green onions","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Cooked white rice","quantity":4.5,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"Coconut aminos","quantity":0.33,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Sesame oil","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"pantry"}]','["Heat 2 tsp oil in a large pan or wok over medium-high heat","Add whisked eggs and scramble until cooked, set aside","Add 1 tbsp oil to pan, then ginger and garlic, cook 30 seconds","Add broccoli and carrots, cook 3-4 minutes until slightly browned","Add chicken and green onions, sauté 1-2 minutes","Add remaining oil, rice, coconut aminos, sesame oil, salt, and pepper flakes","Cook undisturbed 2-3 minutes, stir, then cook another 2-3 minutes","Add scrambled eggs back, garnish with green onions and cilantro"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('spinach-artichoke-meatza','Spinach Artichoke Meatza','Pizza with a ground beef crust topped with creamy spinach and artichoke mixture','american','medium',20,5,25,4,450,1,0,0,0,1,'beef',3,0.773,9,1,'[{"name":"Cream cheese","quantity":8,"unit":"oz","unit_norm":"oz","category":"dairy"},{"name":"Garlic powder","quantity":0.5,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Olive oil","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Garlic","quantity":3,"unit":"tsp","unit_norm":"tsp","category":"produce"},{"name":"Fresh spinach","quantity":8,"unit":"oz","unit_norm":"oz","category":"produce"},{"name":"Artichoke hearts","quantity":14,"unit":"oz","unit_norm":"oz","category":"pantry"},{"name":"Mushrooms","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Italian seasoning","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Ground beef","quantity":1.5,"unit":"lbs","unit_norm":"lb","category":"meat"}]','["Preheat oven to 400°F","Soften cream cheese in microwave, stir in garlic powder and salt","Heat oil in a skillet, add garlic and sauté 30 seconds","Add spinach and sauté 1 minute until wilted","Drain artichokes and add to skillet with mushrooms and Italian seasoning","Spread cream cheese mixture over par-baked meatza crust","Top with spinach-artichoke mixture","Bake until warmed through and edges are crispy"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('enchilada-stuffed-zucchini-boats','Enchilada-Stuffed Zucchini Boats','Hollowed zucchini filled with seasoned ground beef in enchilada sauce','mexican','easy',25,5,30,4,350,1,0,0,0,1,'beef',3,0.892,8,1,'[{"name":"Cooked ground beef","quantity":3.25,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"Enchilada sauce","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Zucchini","quantity":3,"unit":"large","unit_norm":"","category":"produce"},{"name":"Olive oil","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Mexican cheese blend","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"Fresh cilantro","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"produce"},{"name":"Cauliflower rice","quantity":2,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"Lime","quantity":1,"unit":"unit","unit_norm":"","category":"produce"}]','["Preheat oven to 375°F","Stir ground beef into enchilada sauce","Place zucchini halves in casserole dish","Brush boats with oil and season with salt and pepper","Fill each zucchini half with meat sauce","Top with cheese","Bake for 25 minutes until cheese is browned and zucchini is cooked","Serve with cilantro-lime cauliflower rice"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('ground-beef-stroganoff','Ground Beef Stroganoff','Classic stroganoff with mushrooms served over zucchini noodles',NULL,'easy',20,5,25,4,380,1,0,0,0,1,'beef',2,0.892,10,1,'[{"name":"Butter","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"dairy"},{"name":"White onion","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Garlic","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"produce"},{"name":"Cooked ground beef","quantity":4.5,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"Mushrooms","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Chicken broth","quantity":1.5,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"Coconut aminos","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Dijon mustard","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Sour cream","quantity":0.75,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"Zucchini noodles","quantity":6,"unit":"cups","unit_norm":"cup","category":"produce"}]','["Heat butter in a large skillet over medium heat","Add onion and garlic, cook until softened","Add cooked ground beef and mushrooms","Stir in broth, coconut aminos, and Dijon mustard","Simmer for 5-10 minutes until sauce thickens","Remove from heat and stir in sour cream","Season with salt and pepper","Serve over zucchini noodles, garnish with parsley"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('cottage-pie','Cottage Pie','Hearty ground beef filling topped with creamy mashed potatoes',NULL,'medium',30,10,40,6,420,1,0,0,0,1,'beef',2,0.637,11,1,'[{"name":"Olive oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Yellow onion","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":3,"unit":"cloves","unit_norm":"clove","category":"produce"},{"name":"Ground beef","quantity":2,"unit":"lbs","unit_norm":"lb","category":"meat"},{"name":"Tomato paste","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Beef broth","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Frozen peas","quantity":1,"unit":"cup","unit_norm":"cup","category":"frozen"},{"name":"Carrots","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"Yukon Gold potatoes","quantity":2,"unit":"lbs","unit_norm":"lb","category":"produce"},{"name":"Butter","quantity":4,"unit":"tbsp","unit_norm":"tbsp","category":"dairy"},{"name":"Milk","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"dairy"}]','["Preheat oven to 400°F","Heat oil in a large skillet, cook onion and garlic until softened","Add ground beef and cook until browned","Stir in tomato paste, broth, and seasonings","Simmer until sauce thickens","Transfer to a baking dish","Top with mashed potatoes, spreading evenly","Bake 25-30 minutes until potatoes are golden"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('green-chili-chicken-casserole','Green Chili Chicken Casserole','Creamy chicken casserole with green chilis and Mexican flavors','mexican','easy',30,5,35,6,360,1,0,0,0,1,'chicken',3,0.892,8,1,'[{"name":"Cream cheese","quantity":8,"unit":"oz","unit_norm":"oz","category":"dairy"},{"name":"Sour cream","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"Diced green chilis","quantity":8,"unit":"oz","unit_norm":"oz","category":"pantry"},{"name":"Shredded chicken","quantity":4,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"Mexican cheese blend","quantity":1,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"Fresh cilantro","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Cumin","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Garlic powder","quantity":0.5,"unit":"tsp","unit_norm":"tsp","category":"pantry"}]','["Preheat oven to 350°F","Mix cream cheese, sour cream, and green chilis","Layer chicken in a baking dish","Spread cream cheese mixture over chicken","Top with cheese","Bake 25-30 minutes until bubbly","Let rest 5 minutes before serving","Garnish with cilantro"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-parmesan-bake','Chicken Parmesan Bake','Easy baked chicken parmesan without the breading','mediterranean','easy',20,15,35,4,340,1,0,0,0,1,'chicken',4,0.892,8,1,'[{"name":"Chicken breasts","quantity":4,"unit":"unit","unit_norm":"","category":"meat"},{"name":"Italian seasoning","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Marinara sauce","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Mozzarella cheese","quantity":1,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"Parmesan cheese","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"Fresh basil","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Olive oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Garlic powder","quantity":0.5,"unit":"tsp","unit_norm":"tsp","category":"pantry"}]','["Preheat oven to 400°F","Place chicken breasts in a baking dish","Season with Italian seasoning, salt, and pepper","Top each breast with marinara sauce","Sprinkle with mozzarella and parmesan","Bake 20-25 minutes until chicken is cooked through","Broil 2-3 minutes to brown cheese","Garnish with fresh basil"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('balsamic-chicken-sheet-pan-dinner','Balsamic Chicken Sheet Pan Dinner','One-pan roasted chicken with vegetables and balsamic glaze','mediterranean','easy',40,10,50,4,380,1,0,0,1,0,'chicken',2,0.757,7,1,'[{"name":"Chicken thighs","quantity":4,"unit":"unit","unit_norm":"","category":"meat"},{"name":"Broccoli","quantity":2,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"Cherry tomatoes","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Red onion","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"Balsamic vinegar","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Olive oil","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Italian seasoning","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Preheat oven to 400°F","Arrange chicken thighs and vegetables on a sheet pan","Drizzle with olive oil and balsamic vinegar","Season with Italian herbs, salt, and pepper","Roast for 35-40 minutes until chicken is cooked through","Vegetables should be tender and caramelized","Drizzle with additional balsamic before serving"]','clean');
